assignment.solutionCode:
function topTwo(scores) {
  const sorted = scores.slice().sort((a, b) => b - a);
  return sorted.slice(0, 2);
}

const scores = [12, 47, 3, 90, 21];
console.log(topTwo(scores));
console.log(scores);

